// План specs/android-app.md 1.3 / 1.4 (кейс .qa/tests/android-app/offline/OF-02). Pre-Prod, preprod-ttp (TTP Test Locks), EN.
// @writes @data: клиент «QA-AUTO offline #6f8ef9 …» (сохраняется после возврата сети); очистка — Actions → Delete Customer.
import { test, expect } from '../../fixtures';
import {
  OFFLINE_TITLE, ROLE, TEST_PHONE, deleteCustomer, goOffline, goOnline, offlineBanner, offlineSaveMessage, pp, setEnglish, stamp, watchDialogs,
} from './offline-helpers';

test.describe('Офлайн — сохранение без сети (#6f8ef9)', () => {
  for (const device of ['@android', '@desktop'] as const) {
    test(`QA-AUTO: Create Client offline shows an in-app "Nothing was saved" message, keeps the data, and saves once back online #6f8ef9 ${device} @writes @data`, async ({ asUser }) => {
      test.setTimeout(120_000);
      const page = await asUser(ROLE);
      const name = `QA-AUTO offline #6f8ef9 ${stamp()}`;
      const dialogs = watchDialogs(page);
      try {
        await setEnglish(page);
        await page.goto(pp('/CustomerForm?action=new'));
        const contact = page.getByLabel(/^Contact Name/).or(page.locator('input#contact_name')).first();
        const phone = page.getByPlaceholder('(234) 567-8900').first();
        const save = page.getByRole('button', { name: 'Create Client' });
        await expect(save).toBeVisible({ timeout: 30_000 });
        await contact.fill(name);
        await phone.fill(TEST_PHONE);

        // Шаг 2: офлайн → Create Client
        await goOffline(page);
        await expect(offlineBanner(page)).toBeVisible();
        await save.click();

        // Сообщение внутри страницы, не системное окно; данные на месте (источник: «מה רצוי» + «מה קיים»)
        await expect(offlineSaveMessage(page)).toBeVisible();
        await expect(page.getByText(OFFLINE_TITLE).filter({ visible: true }).first()).toBeVisible();
        expect(dialogs, 'системного окна быть не должно').toEqual([]);
        await expect(contact).toHaveValue(name);
        await expect(phone).not.toHaveValue('');
        await expect(page).toHaveURL(/\/CustomerForm/);

        // Шаг 3: онлайн → полоса ушла → Create Client ещё раз
        await goOnline(page);
        await expect(offlineBanner(page)).toHaveCount(0);
        await save.click();
        await expect(page).not.toHaveURL(/action=new/, { timeout: 20_000 });
        expect(dialogs, 'системного окна быть не должно').toEqual([]);

        // Шаг 4: ровно один клиент (без дубля)
        await page.goto(pp('/Customers'));
        await page.getByPlaceholder('Search clients...').fill(name);
        await expect(page.getByText(name, { exact: true }).filter({ visible: true })).toHaveCount(1);
      } finally {
        await deleteCustomer(page, name);
      }
    });
  }
});
